function toHex(bytes) {
  var s = '';
  for (var i = 0; i < bytes.length; i++) {
    var b = bytes[i] & 255;
    s += (b < 16 ? '0' : '') + b.toString(16);
  }
  return s;
}

function frame(payload) {
  var len = payload.length;
  var chk = len;
  for (var i = 0; i < payload.length; i++) chk ^= payload[i];
  return toHex([0xA5, len].concat(payload, [chk & 255]));
}

function int16be(v) {
  var u = v < 0 ? v + 65536 : v;
  return [(u >> 8) & 255, u & 255];
}

function encodeAxis(x) {
  if (typeof x !== 'number' || !isFinite(x)) throw new Error('ARGUMENT: non-finite');
  if (Math.abs(x) > 0.1 + 1e-12) throw new Error('ARGUMENT: out of range');
  var q = Math.round(x * 10000);
  if (q < -1000 || q > 1000) throw new Error('ARGUMENT: out of range');
  return int16be(q);
}

function encode(command) {
  if (Array.isArray(command)) {
    if (command.length !== 2) throw new Error('ARGUMENT: need 2 channels');
    var a = encodeAxis(command[0]);
    var b = encodeAxis(command[1]);
    return frame([0x10].concat(a, b));
  }
  if (command && command.op === 'lift') {
    if (command.position === 'up') return frame([0x20, 1]);
    if (command.position === 'down') return frame([0x20, 0]);
    throw new Error('ARGUMENT: lift position');
  }
  if (command && command.op === 'grip') {
    if (command.state === 'closed') return frame([0x21, 1]);
    if (command.state === 'open') return frame([0x21, 0]);
    throw new Error('ARGUMENT: grip state');
  }
  throw new Error('ARGUMENT: unknown command');
}

function s16(hi, lo) {
  var v = (hi << 8) | lo;
  return v >= 32768 ? v - 65536 : v;
}

function decode(rawReply) {
  if (typeof rawReply !== 'string') throw new Error('FRAME: not string');
  var h = rawReply.trim().toLowerCase();
  if (h.length < 8 || (h.length % 2) !== 0 || !/^[0-9a-f]+$/.test(h)) throw new Error('FRAME: bad hex');
  var bytes = [];
  for (var i = 0; i < h.length; i += 2) bytes.push(parseInt(h.substr(i, 2), 16));
  if (bytes[0] !== 0xA5) throw new Error('FRAME: sync');
  var len = bytes[1];
  if (bytes.length !== len + 3) throw new Error('FRAME: length');
  var chk = len;
  for (var j = 2; j < 2 + len; j++) chk ^= bytes[j];
  if ((chk & 255) !== bytes[bytes.length - 1]) throw new Error('CHECKSUM');
  var p = bytes.slice(2, 2 + len);
  if (p.length < 2) throw new Error('FRAME: payload');
  var status = p[0];
  var op = p[1];
  if (status !== 0) {
    var names = {1:'FRAME',2:'CHECKSUM',3:'NOT_READY',4:'LIMIT',5:'OPCODE',6:'ARGUMENT',7:'COLLISION'};
    throw new Error('DEVICE ERROR ' + status + ' ' + (names[status] || 'UNKNOWN') + ' op=' + op);
  }
  if (op === 0x10) {
    if (p.length !== 7) throw new Error('FRAME: step length');
    return {
      applied: [s16(p[2], p[3]) / 10000, s16(p[4], p[5]) / 10000],
      limited: (p[6] & 1) === 1
    };
  }
  if (op === 0x20) {
    if (p.length !== 4) throw new Error('FRAME: lift length');
    if (p[2] !== 0 && p[2] !== 1) throw new Error('FRAME: lift position');
    return {
      applied: { op: 'lift', position: p[2] === 1 ? 'up' : 'down' },
      limited: (p[3] & 1) === 1
    };
  }
  if (op === 0x21) {
    if (p.length !== 4) throw new Error('FRAME: grip length');
    if (p[2] !== 0 && p[2] !== 1) throw new Error('FRAME: grip state');
    return {
      applied: { op: 'grip', state: p[2] === 1 ? 'closed' : 'open' },
      limited: (p[3] & 1) === 1
    };
  }
  throw new Error('OPCODE: unexpected reply ' + op);
}

