function control(state) {
  var h = state.history || [];
  var tip = state.tip;
  var tgt = state.target;
  var ex = tgt[0] - tip[0];
  var ey = tgt[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (err <= state.tolerancePx) return { action: 'verify' };
  if (state.step >= state.maxActions) return { action: 'stop', reason: 'budget exhausted' };

  var probes = [[0.03, 0], [0, 0.03], [-0.03, 0], [0, -0.03]];
  var n = h.length;
  if (n < 2) return { action: 'move', u: probes[n % 4] };

  // Weighted least squares: delta ~= J * applied, recent samples weighted more.
  var lam = 1e-6;
  var Mxx = lam, Mxy = 0, Myy = lam;
  var N00 = 0, N01 = 0, N10 = 0, N11 = 0;
  var used = 0;
  for (var i = 0; i < n; i++) {
    var rec = h[i];
    var c = rec.applied || rec.command;
    var d = rec.delta;
    if (!c || !d || c.length !== 2 || d.length !== 2) continue;
    if (!isFinite(c[0]) || !isFinite(c[1]) || !isFinite(d[0]) || !isFinite(d[1])) continue;
    var w = Math.pow(0.9, n - 1 - i);
    var c0 = c[0], c1 = c[1], d0 = d[0], d1 = d[1];
    Mxx += w * c0 * c0;
    Mxy += w * c0 * c1;
    Myy += w * c1 * c1;
    N00 += w * d0 * c0;
    N01 += w * d0 * c1;
    N10 += w * d1 * c0;
    N11 += w * d1 * c1;
    used++;
  }
  if (used < 2) return { action: 'move', u: probes[n % 4] };

  var detM = Mxx * Myy - Mxy * Mxy;
  if (!isFinite(detM) || Math.abs(detM) < 1e-12) return { action: 'move', u: probes[n % 4] };
  var i00 = Myy / detM, i01 = -Mxy / detM, i10 = -Mxy / detM, i11 = Mxx / detM;
  // J = N * Minv
  var a = N00 * i00 + N01 * i10;
  var b = N00 * i01 + N01 * i11;
  var c2 = N10 * i00 + N11 * i10;
  var d2 = N10 * i01 + N11 * i11;

  var detJ = a * d2 - b * c2;
  var sv = Math.abs(a) + Math.abs(b) + Math.abs(c2) + Math.abs(d2);
  if (!isFinite(detJ) || Math.abs(detJ) < 1e-4 * sv * sv + 1e-9) {
    // poorly conditioned: probe a different direction to excite the weak axis
    return { action: 'move', u: probes[n % 4] };
  }

  // Solve J u = 0.5 * e
  var gx = 0.5 * ex, gy = 0.5 * ey;
  var u0 = (d2 * gx - b * gy) / detJ;
  var u1 = (-c2 * gx + a * gy) / detJ;
  if (!isFinite(u0) || !isFinite(u1)) return { action: 'move', u: probes[n % 4] };

  var mag = Math.sqrt(u0 * u0 + u1 * u1);
  var maxMag = 0.05;
  if (mag > maxMag) {
    u0 = u0 * maxMag / mag;
    u1 = u1 * maxMag / mag;
  }
  u0 = Math.max(-0.1, Math.min(0.1, u0));
  u1 = Math.max(-0.1, Math.min(0.1, u1));
  return { action: 'move', u: [u0, u1] };
}
